struct legacy_point;
struct obb;

namespace boost::geometry::traits {
template <> struct tag<obb>                  { using type = box_tag; };
template <> struct coordinate_type<obb>      { using type = double; };
template <> struct coordinate_system<obb>    { using type = cs::cartesian; };
template <> struct point_type<obb>           { using type = legacy_point; };

template <int Corner, std::size_t Dimension>
struct indexed_access<obb, Corner, Dimension>
{
    using coordinate_type = double;
    static coordinate_type get(const obb&) {...}
};
} // namespace boost::geometry::traits

