import { Map } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { MaplibreTerradrawControl } from '@watergis/maplibre-gl-terradraw'
import '@watergis/maplibre-gl-terradraw/dist/maplibre-gl-terradraw.css'

const map = new Map({
            container: 'map',
            style: 'https://demotiles.maplibre.org/style.json',
            center: [0, 0],
            zoom: 1,
        });

// As default, all Terra Draw modes are enabled,
// you can disable options if you don't want to use them.

const draw = new MaplibreMeasureControl({
    modes: ['render','point','linestring','polygon','select','delete-selection','delete','download'],
    open: true,
    distanceUnit: 'kilometers', distancePrecision: 2, areaUnit: 'metric', areaPrecision: 2, computeElevation: true
});
map.addControl(draw, 'top-left');

const drawControl = new MaplibreTerradrawControl.MaplibreMeasureControl({
    modes: ['point', 'linestring', 'delete', 'download'],
    open: true,
    // enable the flag to compute elevation
    computeElevation: true,
    // set your own terrainRGB or terrarium source.
    // PNG or WEBP is supported.
    terrainSource: {
        url: 'https://wasac.github.io/rw-terrain-webp/tiles/{z}/{x}/{y}.webp',
        tileSize: 512,
        minzoom: 5,
        maxzoom: 15,
        encoding: 'mapbox'
    }

map.once('load', () => {
    const drawInstance = drawControl.getTerraDrawInstance();
    if (drawInstance) {
        // geojson data to be added
        const geojson = [
            {
                id: '6b438f48-f6da-4649-9212-76f5a1506296',
                type: 'Feature',
                geometry: {
                    type: 'Polygon',
                    coordinates: [
                        [
                            [26.938972246, 25.217617825],
                            [-4.045232861, 25.217617825],
                            [-4.045232861, -7.839055615],
                            [26.938972246, -7.839055615],
                            [26.938972246, 25.217617825]

// As default, all Terra Draw modes are enabled,
// you can disable options if you don't want to use them.
const draw = new MaplibreMeasureControl({
    modes: ['polygon','linestring','point','delete'],
    open: true,
    distanceUnit: 'kilometers', distancePrecision: 2, areaUnit: 'metric', areaPrecision: 2, computeElevation: true
});
map.addControl(draw, 'top-left');

// custom terradraw layer style is following.
modeOptions: {
    polygon: new terraDraw.TerraDrawPolygonMode({
        styles: {
            fillColor: '#F5AEAE',
            fillOpacity: 0.7,
            outlineColor: '#FF0000',
            outlineWidth: 2,
            closingPointColor: '#FAFAFA',
            closingPointWidth: 3,
            closingPointOutlineColor: '#FF0000',
            closingPointOutlineWidth: 1
        }
    }),

        properties: {
            // make sure you put terradraw mode for geojson
            mode: 'polygon'
        }
    }
];
drawInstance?.addFeatures(geojson);

map.addControl(drawControl, 'top-left');
map.addControl(
    new maplibregl.NavigationControl({
        visualizePitch: true,
        showCompass: true
    }),
    'bottom-right'
);
map.addControl(new maplibregl.GlobeControl(), 'bottom-right');

const drawControl = new MaplibreTerradrawControl.MaplibreMeasureControl({
    modes: ['point', 'linestring', 'polygon', 'delete'],
    open: true,
    computeElevation: true
});
// set your own font glyphs
// make sure the font is supported by your map style.
// Please also see the documentation of glyphs for maplibre at https://maplibre.org/maplibre-style-spec/glyphs/
drawControl.fontGlyphs = ['Open Sans Italic'];
map.addControl(drawControl, 'top-left');
